lastmod:
 is the build date for every page, so
    each deploy claimed all ~950 pages changed and Google learns to ignore the field; this uses the
    page's last commit from git-revision-date-localized instead. And the generated chapter pages
    (commentaries//chapter-NNN.md) are left out: they are link lists, marked noindex in
    main.html, and a sitemap should not offer a page the page itself tells crawlers to skip. -#}

{%- for file in pages -%}
    {%- set src = file.page.file.src_uri -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) and not (src.startswith('commentaries/') and '/chapter-' in src) %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if file.page.meta.git_revision_date_localized_raw_iso_date %}{{ file.page.meta.git_revision_date_localized_raw_iso_date }}{% endif %}

    {%- endif -%}
{% endfor %}
